import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { QRCodeSVG } from 'qrcode.react';

const FileDetailsPage = () => {
  const [fileDetails, setFileDetails] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [copied, setCopied] = useState(false);
  const [activeTab, setActiveTab] = useState('qr');
  const { uuid } = useParams();

  useEffect(() => {
    const fetchFileDetails = async () => {
      try {
        const response = await axios.get(`/api/files/${uuid}`);
        setFileDetails(response.data);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching file details:', error);
        setError('File not found or has been removed');
        setLoading(false);
      }
    };

    fetchFileDetails();
  }, [uuid]);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(fileDetails.downloadLink);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const formatDate = (dateString) => {
    const options = { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  const getFileTypeIcon = (type) => {
    switch(type) {
      case 'image': return '🖼️';
      case 'document': return '📄';
      case 'video': return '🎬';
      case 'audio': return '🎵';
      case 'archive': return '🗄️';
      default: return '📁';
    }
  };

  if (loading) {
    return (
      <div className="loading-spinner">
        <p>Loading file details...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error-message">
        <p>{error}</p>
      </div>
    );
  }

  return (
    <div className="file-sharing-page">
      <div className="file-details-container">
        <div className="file-details-card">
          <div className="file-details-header">
            <h2>File Ready to Share!</h2>
            <div className="file-info">
              <span className="file-type-icon">
                {getFileTypeIcon(fileDetails.type)}
              </span>
              <span className="file-name">{fileDetails.filename}</span>
              <span className="file-size">
                {(fileDetails.size / (1024 * 1024)).toFixed(2)} MB
              </span>
              <span className="file-type">
                {fileDetails.type && fileDetails.type.charAt(0).toUpperCase() + fileDetails.type.slice(1)} 
                {fileDetails.extension && `(.${fileDetails.extension})`}
              </span>
            </div>
          </div>

          <div className="share-tabs">
            <div className="tab-headers">
              <button 
                className={`tab-btn ${activeTab === 'qr' ? 'active' : ''}`}
                onClick={() => setActiveTab('qr')}
              >
                QR Code
              </button>
              <button 
                className={`tab-btn ${activeTab === 'link' ? 'active' : ''}`}
                onClick={() => setActiveTab('link')}
              >
                Share Link
              </button>
            </div>

            <div className="tab-content">
              {activeTab === 'qr' && (
                <div className="qr-tab">
                  <div className="qr-container">
                    <QRCodeSVG 
                      value={fileDetails.downloadLink} 
                      size={200}
                      level="H"
                      includeMargin={true}
                      bgColor="#FFFFFF"
                      fgColor="#000000"
                    />
                  </div>
                  <p className="qr-instructions">Scan this QR code to download the file</p>
                </div>
              )}

              {activeTab === 'link' && (
                <div className="link-tab">
                  <div className="link-container">
                    <input 
                      type="text" 
                      value={fileDetails.downloadLink} 
                      readOnly 
                      className="link-input"
                    />
                    <button 
                      className="copy-btn" 
                      onClick={handleCopyLink}
                    >
                      {copied ? 'Copied!' : 'Copy'}
                    </button>
                  </div>
                  <p className="link-instructions">Share this link with anyone to download the file</p>
                </div>
              )}
            </div>
          </div>

          <div className="file-metadata">
            {fileDetails.uploadDate && <p><strong>Uploaded:</strong> {formatDate(fileDetails.uploadDate)}</p>}
            {fileDetails.downloadCount !== undefined && <p><strong>Downloads:</strong> {fileDetails.downloadCount}</p>}
          </div>

          <div className="download-section">
            <a 
              href={`/api/files/download/${uuid}`} 
              className="download-btn"
              download
            >
              Download File
            </a>
          </div>
        </div>
      </div>

      <div className="features-section">
        <h2>Simple, Secure File Sharing</h2>
        <p className="feature-description">
          Share files with anyone, anywhere, without registration or complicated steps.
        </p>
        <div className="feature-list">
          <div className="feature-item">
            <span className="feature-icon">🔒</span>
            <span className="feature-text">Secure Sharing</span>
          </div>
          <div className="feature-item">
            <span className="feature-icon">⚡</span>
            <span className="feature-text">Fast Downloads</span>
          </div>
          <div className="feature-item">
            <span className="feature-icon">📱</span>
            <span className="feature-text">Works on All Devices</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FileDetailsPage;
